<template><view><SiteHeader active="events"/><view class="wrap"><view class="fde-feature">
  <button class="fde-trigger" role="button" tabindex="0" :aria-expanded="fdeOpen" aria-controls="fde-details" @click="fdeOpen=!fdeOpen" @keydown.enter.prevent="fdeOpen=!fdeOpen" @keydown.space.prevent="fdeOpen=!fdeOpen">
    <image class="fde-thumb" src="/static/assets/fde-cover.jpg" mode="aspectFit" />
    <view class="fde-preview"><text class="fde-kicker">{{ conferenceLabel }} · FDE 实战与线下交流</text><text class="fde-title">AI航海家FDE大会</text><text class="fde-meta">{{ conference ? formatDate(conference.startTime) + ' · ' + (conference.city || '北京') + ' ' + (conference.district || '') : '活动时间与地点以报名资料为准' }}</text><text class="fde-status">{{ conferenceStatus }}</text><text class="fde-teaser">把 AI 做进真实业务，和同行聊获客、交付与协作。</text></view>
    <view class="fde-toggle">{{ fdeOpen ? '收起专题' : '展开查看' }} <text>{{ fdeOpen ? '⌃' : '⌄' }}</text></view>
  </button>
  <view v-if="fdeOpen" id="fde-details" class="fde-details">
    <view class="fde-details-copy"><text class="fde-detail-label">真实业务 · 同行交流</text><text class="fde-detail-title">下一站，FDE。<br/>把 AI 做进真实生意。</text><text class="fde-body">企业 AI 落地的机会，藏在真实业务问题里。想入局，或已在做，都可以来现场和同行聊获客、交付与协作。</text><text class="fde-highlights">同行交流　·　实战拆解　·　资源连接</text><text class="fde-program">7 位主嘉宾 · 20 多场主题夜话</text><view v-if="conference" class="fde-info"><text>{{ formatDate(conference.startTime) }}</text><text>{{ conference.city }} · {{ conference.district }}</text><text v-if="conference.submitEnd">报名截止 {{ formatDate(conference.submitEnd) }}</text></view><view class="fde-actions"><button class="fde-register" @click="conferenceOpen=true">{{ registrationLabel }} →</button><button class="fde-topic" @click="goFdeTopic">先看 FDE 实战 →</button></view><text class="fde-note">活动信息来自已收录资料，时间、购票与参与条件以报名图和入口说明为准。</text></view>
    <view class="fde-poster-wrap"><image class="fde-poster" src="/static/assets/fde-cover.jpg" mode="widthFix" /><text>AI航海家FDE大会 · 活动海报</text></view>
  </view>
</view><view class="headline"><view><text class="kicker">CITY MEETUPS</text><text class="heading">同城 AI 活动</text></view><text class="muted">{{cities.length}} 个城市 · {{feedMeta.source}}</text></view><scroll-view scroll-x class="filters"><view class="filter-row"><button :class="{on:!city}" @click="city=''">全部城市</button><button v-for="c in cities" :key="c" :class="{on:city===c}" @click="city=c">{{c}}</button></view></scroll-view><view v-if="!visibleGroups.length" class="empty">暂未收录符合条件的 AI 活动。</view><view v-for="group in visibleGroups" :key="group.city" class="city-card"><view class="city-head"><view><text class="kicker">同城 AI 活动 / MEETUP</text><text class="city-name">{{group.city}}</text></view><text>{{group.items.length}} 场收录活动</text></view><view class="columns" :class="{'has-empty': !filterBucket(group,'近期与进行中').length || !filterBucket(group,'已结束').length}"><view v-for="bucket in ['近期与进行中','已结束']" :key="bucket" class="column" :class="{'is-empty': !filterBucket(group,bucket).length}"><text class="column-title">{{bucket}}</text><template v-for="item in showItems(group,bucket)" :key="item.id"><view class="event" @click="selected=item"><view class="event-top"><text>{{item.typeText || '同城活动'}}</text><text>{{stateLabel(item)}}</text></view><text class="event-title">{{item.name}}</text><text class="event-meta">{{formatDate(item.startTime)}} · {{item.district || item.city}}</text><view class="event-bottom"><text>站内查看详情 →</text><text @click.stop="toggleSave(item)">{{isSaved(item)?'已收藏':'收藏'}}</text></view></view></template><text v-if="!filterBucket(group,bucket).length" class="muted">暂无已收录活动</text><button v-if="filterBucket(group,bucket).length>2" class="more" @click="toggleMore(group.city,bucket)">{{expanded[group.city+bucket]?'收起':`查看更多（${filterBucket(group,bucket).length-2}）`}}</button></view></view></view></view><CampFooter/><view v-if="conferenceOpen" class="overlay" @click="conferenceOpen=false"><view class="modal conference-modal" @click.stop><view class="modal-top"><text>线下大会报名</text><text @click="conferenceOpen=false">关闭 ✕</text></view><text class="conference-modal-title">{{ registrationLabel === '查看大会报名图' ? '扫码了解大会报名' : '查看大会报名资料' }}</text><text class="conference-modal-copy">{{ conferenceStatus }}。请先阅读图片中的购票说明，具体大会信息和报名安排以二维码入口为准。</text><image class="conference-image" src="/static/assets/conference-invite.png" mode="widthFix" @click="previewConference"/><text class="conference-image-tip">点击图片放大，手机可长按识别二维码</text><button class="conference-button" @click="previewConference">查看完整报名图</button></view></view><view v-if="selected" class="overlay" @click="selected=null"><view class="modal" @click.stop><view class="modal-top"><text>活动资料 · {{stateLabel(selected)}}</text><text @click="selected=null">关闭 ✕</text></view><text class="modal-title">{{selected.name}}</text><text class="event-meta">{{formatDate(selected.startTime)}} · {{selected.city}} {{selected.district}}</text><text class="body">{{selected.description || selected.summary || '活动具体内容请以原始资料为准。'}}</text><view class="reviews"><text class="column-title">本场活动反馈</text><view v-for="r in selectedReviews" :key="r.sourceId" class="review"><text>{{r.author}} · {{r.attribution}}</text><text>{{r.text}}</text></view><text v-if="!selectedReviews.length" class="muted">暂未收录能确认属于本场的评价。</text></view><button class="action" @click="goCamp">了解三天体验营 →</button></view></view></view></template>
<script setup>
import {computed,ref,onUnmounted} from 'vue';
import {onLoad} from '@dcloudio/uni-app';
import SiteHeader from '../../components/SiteHeader.vue';
import CampFooter from '../../components/CampFooter.vue';
import {events,eventReviews,feedMeta} from '../../data/content.js';
import {getSaved,setSaved} from '../../data/storage.js';
const city=ref(''),selected=ref(null),expanded=ref({}),saved=ref(getSaved()),conferenceOpen=ref(false),fdeOpen=ref(false),now=ref(Date.now());
const conference=computed(()=>events.find(e=>String(e?.id)==='10533')||null);
const conferenceLabel=computed(()=>{const e=conference.value;if(!e||/CANCEL|ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||'')||(Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value))return '活动资料';return '本期关注'});
const conferenceStatus=computed(()=>{const e=conference.value;if(!e)return '报名状态以活动入口说明为准';if(/CANCEL/i.test(e.lifecycleStatus||''))return '活动已取消';if(/ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||''))return '活动已结束';if(Number(e.submitEnd)>0&&Number(e.submitEnd)*1000<now.value)return '报名已截止';if(e.full)return '资料显示名额已满';if(Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value)return '活动状态待确认';return '报名与名额以入口实时说明为准'});
const registrationLabel=computed(()=>{const e=conference.value;if(!e||/CANCEL|ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||'')||(Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value)||(Number(e.submitEnd)>0&&Number(e.submitEnd)*1000<now.value)||e.full)return '查看活动资料';return '查看大会报名图'});
const clock=setInterval(()=>{now.value=Date.now()},60000);onUnmounted(()=>clearInterval(clock));
function goFdeTopic(){uni.navigateTo({url:'/pages/topic/index?slug=fde'})}
onLoad(options=>{if(options?.view==='conference')conferenceOpen.value=true});
function previewConference(){uni.previewImage({current:'/static/assets/conference-invite.png',urls:['/static/assets/conference-invite.png']})}
const ai=/(?:^|[^a-z])ai(?=$|[^a-z]|ppt|agent|video)|人工智能|智能体|大模型|生成式|AIGC|GPT|Claude|Codex|Gemini|Grok|Cursor|Copilot|OpenAI|DeepSeek|豆包|通义千问|文心一言|(?:^|[^a-z])(?:FDE|Agent|MCP|LLM)(?=$|[^a-z])|workbuddy|seedance|comfyui|minimax/i;
function isAiEvent(e){if(ai.test(`${e.name||''} ${e.typeText||''}`))return true;return /(?:本期|本次|本场|活动|聚会|分享|主题|从).{0,16}(?:AI|人工智能|智能体|大模型|FDE|Agent|MCP)/i.test(String(e.summary||e.description||'').slice(0,300))}
const groups=computed(()=>{const m=new Map();for(const e of events.filter(e=>e&&e.city&&isAiEvent(e)&&!/CANCEL/i.test(e.lifecycleStatus||''))){if(!m.has(e.city))m.set(e.city,[]);m.get(e.city).push(e)}return [...m.entries()].map(([city,items])=>({city,items}));});
const cities=computed(()=>groups.value.map(g=>g.city));
const visibleGroups=computed(()=>groups.value.filter(g=>!city.value||g.city===city.value));
const selectedReviews=computed(()=>eventReviews.filter(r=>selected.value&&String(r.eventId)===String(selected.value.id)));
function ended(e){return /ENDED|FINISHED|COMPLETED/.test(e.lifecycleStatus||'')}
function stateLabel(e){return ended(e)?'已结束':Number(e.startTime)*1000>Date.now()?'即将开始':'进行中或状态待确认'}
function formatDate(t){if(!t)return '时间待确认';const d=new Date(Number(t)*1000+8*3600000);if(Number.isNaN(d.getTime()))return '时间待确认';return `${d.getUTCMonth()+1}月${d.getUTCDate()}日 ${String(d.getUTCHours()).padStart(2,'0')}:${String(d.getUTCMinutes()).padStart(2,'0')}（北京时间）`}
function filterBucket(g,b){return g.items.filter(e=>b==='已结束'?ended(e):!ended(e)).sort((a,z)=>b==='已结束'?z.startTime-a.startTime:a.startTime-z.startTime)}
function showItems(g,b){const a=filterBucket(g,b);return expanded.value[g.city+b]?a:a.slice(0,2)}
function toggleMore(c,b){const k=c+b;expanded.value={...expanded.value,[k]:!expanded.value[k]}}
function isSaved(e){return saved.value.includes(`event:${e.id}`)}
function toggleSave(e){const k=`event:${e.id}`;saved.value=isSaved(e)?saved.value.filter(x=>x!==k):[...saved.value,k];setSaved(saved.value)}
function goCamp(){selected.value=null;uni.navigateTo({url:'/pages/camp/index'})}
</script>
<style scoped>.wrap{max-width:1200px;margin:0 auto;padding:35rpx 28rpx;color:#173d2c}.hero{padding:60rpx;background:#153a29;color:#eff6e7;border-radius:12rpx}.eyebrow,.kicker{display:block;font-size:21rpx;color:#a7c979;font-weight:700;letter-spacing:1rpx}.hero-title{display:block;font-size:62rpx;font-weight:750;margin:15rpx 0}.hero-copy,.disclaimer{display:block;color:#c2d4bb;font-size:27rpx;line-height:1.7}.disclaimer{font-size:22rpx;color:#a2b89c;margin-top:20rpx}.headline{display:flex;justify-content:space-between;align-items:end;margin:48rpx 0 20rpx}.heading,.city-name{display:block;font-size:40rpx;font-weight:700;margin-top:10rpx}.muted{font-size:24rpx;color:#859987;line-height:1.7}.filters{white-space:nowrap;margin-bottom:20rpx}.filter-row{display:flex;gap:14rpx;width:max-content;min-width:100%}.filter-row button{flex-shrink:0;white-space:nowrap}.filter-row button,.more{font-size:24rpx;background:#f1f5ec;color:#547459;margin:0;line-height:2.6;padding:0 24rpx}.filter-row button.on{background:#224e36;color:white}.city-card{background:#fff;border:1px solid #dfe9dc;border-radius:12rpx;margin:22rpx 0;overflow:hidden}.city-head{display:flex;align-items:end;justify-content:space-between;background:#dcebd3;padding:27rpx;color:#376249;font-size:23rpx}.columns{display:grid;grid-template-columns:1fr 1fr}.column{padding:25rpx;min-width:0}.column+.column{border-left:1px solid #e5ece0}.column-title{display:block;font-size:27rpx;font-weight:700;color:#2d5b3f}.event{padding:25rpx 0;border-bottom:1px solid #edf1eb}.event-top,.event-bottom{display:flex;justify-content:space-between;color:#8ba085;font-size:21rpx;gap:10rpx}.event-title,.event-meta{display:block}.event-title{font-size:28rpx;font-weight:700;margin:14rpx 0;color:#264e36;line-height:1.5}.event-meta{font-size:23rpx;color:#859b84;line-height:1.6}.event-bottom{color:#5f895f;margin-top:22rpx}.more{margin-top:20rpx}.overlay{position:fixed;z-index:99;inset:0;background:#0008;display:flex;align-items:center;justify-content:center;padding:22rpx}.modal{background:white;border-radius:15rpx;padding:35rpx;max-width:800px;width:100%;max-height:80vh;overflow:auto}.modal-top{display:flex;justify-content:space-between;color:#7a9574;font-size:22rpx}.modal-title{display:block;font-size:39rpx;font-weight:700;margin:20rpx 0}.body{display:block;white-space:pre-wrap;font-size:26rpx;line-height:1.8;color:#536f5c;margin:25rpx 0}.reviews{padding-top:20rpx;border-top:1px solid #e0eadb}.review text{display:block;font-size:23rpx;color:#678069;line-height:1.7;margin:10rpx 0}.action{background:#29583b;color:white;margin:25rpx 0 0;font-size:25rpx}.empty{padding:40rpx;color:#829880}@media(max-width:600px){.hero{padding:35rpx}.hero-title{font-size:44rpx}.columns{grid-template-columns:1fr}.column+.column{border-left:0;border-top:1px solid #e5ece0}.headline{align-items:start;gap:10rpx;flex-direction:column}}
.fde-feature{overflow:hidden;background:#102f22;color:#edf5e7;border-radius:10px}.fde-trigger{display:flex;align-items:center;gap:20px;text-align:left;width:100%;padding:18px 24px;margin:0;background:#102f22;border:0;color:inherit;line-height:normal;border-radius:0}.fde-trigger::after{border:0}.fde-thumb{width:70px;height:104px;flex-shrink:0;border-radius:4px}.fde-preview{flex:1;min-width:0}.fde-preview text,.fde-details-copy text,.fde-poster-wrap text{display:block}.fde-kicker,.fde-detail-label{font-size:12px;font-weight:700;color:#bddd8c}.fde-title{font-size:23px;font-weight:800;line-height:1.3;color:#fff;margin-top:6px}.fde-meta,.fde-teaser{font-size:13px;line-height:1.6;color:#bfceb8;margin-top:5px}.fde-toggle{border:1px solid #779563;padding:10px 14px;border-radius:6px;white-space:nowrap;font-size:13px;font-weight:700;color:#d4eaaa}.fde-toggle text{margin-left:5px}.fde-details{display:grid;grid-template-columns:minmax(0,1fr) 255px;gap:44px;align-items:center;border-top:1px solid #54705a;padding:40px 45px}.fde-details-copy{min-width:0}.fde-detail-title{font-size:38px;line-height:1.25;color:#fff;font-weight:800;margin:13px 0}.fde-body{font-size:15px;line-height:1.9;color:#d0ddcc;max-width:650px}.fde-highlights{font-size:13px;font-weight:700;color:#e1eedb;margin-top:16px}.fde-program{font-size:13px;color:#c9dcac;margin-top:11px}.fde-info{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:18px;color:#c0d1b9;font-size:13px;line-height:1.6}.fde-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:22px}.fde-register,.fde-topic{margin:0;padding:0 18px;line-height:43px;font-size:13px;font-weight:700;border-radius:6px}.fde-register{background:#f15a24;color:#fff}.fde-topic{background:transparent;color:#d5e9c8;border:1px solid #66836e}.fde-register::after,.fde-topic::after{border:0}.fde-note{font-size:11px;line-height:1.7;color:#9eb39c;margin-top:14px}.fde-poster-wrap{width:100%;max-width:255px}.fde-poster{display:block;width:100%;border-radius:6px}.fde-poster-wrap text{font-size:11px;color:#a8bba4;margin-top:7px}.fde-trigger:focus-visible,.fde-register:focus-visible,.fde-topic:focus-visible{outline:2px solid #f6cf71;outline-offset:-3px}@media(max-width:700px){.fde-trigger{padding:16px;gap:13px;flex-wrap:wrap}.fde-thumb{width:55px;height:82px}.fde-kicker{font-size:11px}.fde-title{font-size:18px}.fde-meta,.fde-teaser{font-size:12px}.fde-toggle{margin-left:68px;padding:8px 12px}.fde-details{grid-template-columns:1fr;gap:25px;padding:24px 20px}.fde-detail-title{font-size:29px}.fde-poster-wrap{max-width:190px}.fde-info{display:block}.fde-info text{margin-top:6px}}
.columns.has-empty{grid-template-columns:1fr}.columns.has-empty .column+.column{border-left:0;border-top:1px solid #e5ece0}.column.is-empty{display:flex;align-items:center;gap:14px;padding:14px 18px}.column.is-empty .column-title,.column.is-empty .muted{font-size:12px}.conference-card{display:flex;align-items:center;justify-content:space-between;gap:20rpx;background:#fffaf1;border:1px solid #efdfbe;border-radius:12rpx;padding:30rpx;margin-top:24rpx}.conference-card-copy text{display:block}.conference-label{color:#ca662d;font-size:21rpx;font-weight:700}.conference-title{font-size:31rpx;font-weight:750;color:#173d2c;margin-top:8rpx}.conference-subtitle{font-size:22rpx;color:#748978;margin-top:8rpx;line-height:1.5}.conference-cta{font-size:23rpx;font-weight:700;color:#d85d26;white-space:nowrap}.conference-modal{max-width:500px}.conference-modal-title,.conference-modal-copy,.conference-image-tip{display:block}.conference-modal-title{font-size:36rpx;font-weight:750;margin:20rpx 0 12rpx}.conference-modal-copy,.conference-image-tip{font-size:23rpx;line-height:1.7;color:#718778}.conference-image{width:100%;margin-top:18rpx;display:block}.conference-image-tip{text-align:center;margin-top:8rpx}.conference-button{margin:20rpx 0 0;background:#ed5a26;color:#fff;font-size:25rpx}.conference-button:after{border:0}
.fde-status{font-size:11px;line-height:1.5;color:#d3dfb8;margin-top:4px}
@media(max-width:700px){.fde-trigger{display:grid;grid-template-columns:55px minmax(0,1fr);gap:10px 13px;align-items:start}.fde-thumb{grid-row:1 / 3}.fde-preview{grid-column:2}.fde-toggle{grid-column:2;justify-self:start;margin:0}}
</style>
